import Foundation

/// Candidates stay disconnected until timing and behavioral checks justify promotion.
nonisolated enum StorageSelectionCandidate {
    static func originalLargest(_ files: [ScannedFile]) -> [ScannedFile] {
        Array(files.sorted { $0.byteCount > $1.byteCount }.prefix(10))
    }

    static func largest(_ files: [ScannedFile]) -> [ScannedFile] {
        var result: [ScannedFile] = []
        result.reserveCapacity(10)
        for file in files {
            // Strict comparison preserves input order for ties, including unknown sizes.
            if result.count == 10, file.byteCount <= result[9].byteCount { continue }
            let index = result.firstIndex { file.byteCount > $0.byteCount } ?? result.count
            result.insert(file, at: index)
            if result.count > 10 { result.removeLast() }
        }
        return result
    }

    static func originalSources(_ sources: [URL]) -> [URL] {
        sources.reduce(into: [URL]()) { result, source in
            let normalized = source.standardizedFileURL
            if !result.contains(where: { $0.standardizedFileURL == normalized }) {
                result.append(source)
            }
        }
    }

    static func sources(_ sources: [URL]) -> [URL] {
        var seen: Set<URL> = []
        return sources.filter { seen.insert($0.standardizedFileURL).inserted }
    }
}
